begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','cancel_flight',array['uuid'],'Flight cancellation RPC exists');
insert into auth.users(id,email) select ('19900000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'cancel-'||n||'@example.invalid' from generate_series(1,7) n;
insert into public.memberships(user_id,role) select ('19900000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=6 then 'admin' else 'member' end::public.member_role from generate_series(1,6) n;
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) select ('19900000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Cancellation pilot','KPAO','licensed' from generate_series(2,5) n;
insert into public.flights(id,owner_id,departure_airport,destination_airport,departure_at,departure_timezone,aircraft_description,pilot_places,visibility,notes)
select ('19910000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'19900000-0000-4000-8000-000000000001','KPAO','KSQL',now()+interval '2 days','UTC','C172',2,case when n=1 then 'PRIVATE' else 'NETWORK' end::public.flight_visibility,'Retained flight note' from generate_series(1,4) n;
insert into public.flight_recipients(flight_id,user_id) select '19910000-0000-4000-8000-000000000001',('19900000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(2,5) n;
insert into public.flight_requests(id,flight_id,requester_id,introductory_note) select ('19920000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'19910000-0000-4000-8000-000000000001',('19900000-0000-4000-8000-'||lpad((n+1)::text,12,'0'))::uuid,'Retained request note' from generate_series(1,4) n;
update public.flight_requests set status=case id when '19920000-0000-4000-8000-000000000002' then 'accepted'::public.flight_request_status when '19920000-0000-4000-8000-000000000003' then 'declined'::public.flight_request_status else 'withdrawn'::public.flight_request_status end where id<>'19920000-0000-4000-8000-000000000001';
create temporary table original_flights as select * from public.flights where id::text like '19910000%';
create temporary table original_requests as select * from public.flight_requests where flight_id='19910000-0000-4000-8000-000000000001';
create function pg_temp.actor(n integer) returns text language sql as $$select set_config('request.jwt.claims',json_build_object('sub',('19900000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'role','authenticated','user_metadata',json_build_object('role','admin'))::text,true);$$;
create function pg_temp.cancel(f integer default 1) returns jsonb language sql as $$select public.cancel_flight(('19910000-0000-4000-8000-'||lpad(f::text,12,'0'))::uuid);$$;
select ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.cancel_flight(uuid)'::regprocedure),'Cancellation definer fixes empty search path');
select ok(has_function_privilege('authenticated','public.cancel_flight(uuid)','EXECUTE'),'Authenticated execute granted');
select ok(not has_function_privilege('anon','public.cancel_flight(uuid)','EXECUTE'),'Anonymous execute revoked');
select ok(not has_function_privilege('service_role','public.cancel_flight(uuid)','EXECUTE'),'Service role execute revoked');
set local role anon;
select throws_ok($$select pg_temp.cancel()$$,'42501',null,'Anonymous denied');
reset role;
set local role service_role;
select throws_ok($$select pg_temp.cancel()$$,'42501',null,'Service role denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select pg_temp.cancel()$$,'42501',null,'Missing identity denied');
select pg_temp.actor(7);
select throws_ok($$select pg_temp.cancel()$$,'42501',null,'Missing membership denied');
select pg_temp.actor(2);
select throws_ok($$select pg_temp.cancel()$$,'42501',null,'Requester cannot spoof admin in JWT metadata');
select pg_temp.actor(1);
select throws_ok($$select pg_temp.cancel(99)$$,'42501',null,'Missing flight shares safe denial');
select throws_ok($$select public.cancel_flight(null)$$,'22023',null,'Null input rejected');
select throws_ok($$update public.flights set status='cancelled'$$,'42501',null,'Owner direct lifecycle updates denied');
reset role;
create function pg_temp.reject_cancel() returns trigger language plpgsql as $$begin raise exception 'Fixture failure' using errcode='23514'; end;$$;
create trigger fixture_reject_cancel before update on public.flights for each row when (new.status='cancelled') execute function pg_temp.reject_cancel();
set local role authenticated;
select throws_ok($$select pg_temp.cancel()$$,'23514',null,'Failed flight write rolls back cancellation');
reset role;
select results_eq($$select to_jsonb(r) from public.flight_requests r where flight_id='19910000-0000-4000-8000-000000000001' order by id$$,$$select to_jsonb(r) from original_requests r order by id$$,'Failed cancellation rolls back all request closures');
drop trigger fixture_reject_cancel on public.flights;
set local role authenticated;
select is(pg_temp.cancel(),'{"code":"cancelled","flightId":"19910000-0000-4000-8000-000000000001","status":"cancelled"}'::jsonb,'Owner without profile cancels with minimal confirmation');
reset role;
select is((select count(*)::integer from public.flight_requests where flight_id='19910000-0000-4000-8000-000000000001' and status in ('pending','accepted')),0,'All active requests closed');
select is((select count(*)::integer from public.flight_requests where flight_id='19910000-0000-4000-8000-000000000001' and status='cancelled'),2,'Pending and accepted become cancelled');
select results_eq($$select id,flight_id,requester_id,introductory_note,created_at from public.flight_requests where flight_id='19910000-0000-4000-8000-000000000001' order by id$$,$$select id,flight_id,requester_id,introductory_note,created_at from original_requests order by id$$,'Request identities, notes and creation history preserved');
select results_eq($$select to_jsonb(r) from public.flight_requests r where status in ('declined','withdrawn') and flight_id='19910000-0000-4000-8000-000000000001' order by id$$,$$select to_jsonb(r) from original_requests r where status in ('declined','withdrawn') order by id$$,'Terminal request rows unchanged');
select is((select to_jsonb(f)-'status'-'updated_at' from public.flights f where id='19910000-0000-4000-8000-000000000001'),(select to_jsonb(f)-'status'-'updated_at' from original_flights f where id='19910000-0000-4000-8000-000000000001'),'Flight history and audience attributes retained');
select is((select count(*)::integer from public.flight_recipients where flight_id='19910000-0000-4000-8000-000000000001'),4,'Private audience preserved');
create temporary table cancelled_snapshot as select to_jsonb(f) row from public.flights f where id='19910000-0000-4000-8000-000000000001';
create temporary table closed_snapshot as select to_jsonb(r) row from public.flight_requests r where flight_id='19910000-0000-4000-8000-000000000001' order by id;
set local role authenticated;
select pg_temp.actor(1);
select is(pg_temp.cancel()->>'code','already_cancelled','Retry confirms cancelled flight');
select is(public.decide_flight_request('19910000-0000-4000-8000-000000000001','19920000-0000-4000-8000-000000000001','accepted')->>'code','request_conflict','Cancellation prevents acceptance');
select pg_temp.actor(2);
select is(public.submit_flight_interest('19910000-0000-4000-8000-000000000001')->>'code','flight_unavailable','Cancelled flight prevents request resubmission');
select is((select status::text from public.flight_requests where id='19920000-0000-4000-8000-000000000001'),'cancelled','Requester reads cancelled history');
select pg_temp.actor(5);
select is(public.submit_flight_interest('19910000-0000-4000-8000-000000000001')->>'code','flight_unavailable','Withdrawn history cannot resubmit to closed flight');
select pg_temp.actor(6);
select is(pg_temp.cancel(2)->>'code','cancelled','Active admin can cancel another owner flight without profile');
reset role;
select is((select to_jsonb(f) from public.flights f where id='19910000-0000-4000-8000-000000000001'),(select row from cancelled_snapshot),'Retry does not alter flight timestamps');
select results_eq($$select to_jsonb(r) from public.flight_requests r where flight_id='19910000-0000-4000-8000-000000000001' order by id$$,$$select row from closed_snapshot$$,'Retry and rejected operations do not alter request timestamps');
update public.flights set departure_at=now()-interval '1 day' where id='19910000-0000-4000-8000-000000000003';
update public.flights set status='completed' where id='19910000-0000-4000-8000-000000000004';
set local role authenticated;
select pg_temp.actor(1);
select is(pg_temp.cancel(3)->>'code','cancelled','Elapsed open flight may be closed');
select is(pg_temp.cancel(4),'{"code":"flight_conflict"}'::jsonb,'Completed flight cannot become cancelled');
reset role;
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Fixture' where user_id in ('19900000-0000-4000-8000-000000000001','19900000-0000-4000-8000-000000000006');
set local role authenticated;
select pg_temp.actor(1);
select throws_ok($$select pg_temp.cancel()$$,'42501',null,'Disabled owner cannot confirm cancellation');
select pg_temp.actor(2);
select throws_ok($$select pg_temp.cancel()$$,'42501',null,'Unrelated member cannot confirm cancelled flight');
select pg_temp.actor(6);
select throws_ok($$select pg_temp.cancel()$$,'42501',null,'Disabled admin cannot cancel');
reset role;
update public.memberships set status='active',disabled_at=null,disabled_reason=null where user_id='19900000-0000-4000-8000-000000000006';
set local role authenticated;
select is(pg_temp.cancel()->>'code','already_cancelled','Active admin can confirm closure for disabled owner');
reset role;
select * from finish();
rollback;
